<template><div class="native-visual" :class="{'native-readonly':readOnly}"><section class="native-blocks"><div class="native-panel-caption"><span>VISUAL EDITOR</span><KsButton size="small" @click="selected=''">Flow 属性</KsButton></div><div v-if="error" class="native-error">{{error}}</div><template v-if="doc">
<BlockSectionCard v-if="controlled" name="device-steps" title="设备任务" :icon="Console" :count="steps.length" addLabel="添加步骤" @add="addStep"><p class="native-note">同一受控执行中的串行步骤 · 目标和通道在运行前预检</p><LeafBlockCard v-for="(step,index) in steps" :key="step.id" :block="{...step,type:'keel.device.'+step.kind}" :path="`inputs.steps[${index}]`" :selected="selected==='step:'+step.id" :focused="selected==='step:'+step.id" :showOpenSplit="false" :showDuplicate="false" :runnable="false" :draggable="false" @select="selected='step:'+step.id" @delete="removeStep(step.id)"/></BlockSectionCard>
<BlockSectionCard v-for="branch in branches.filter(b=>b==='tasks'||doc[b]?.length)" :key="branch" :name="branch" :title="branch==='tasks'?'Flow Tasks':branch" :icon="ViewSequential" :count="doc[branch]?.length||0" addLabel="添加任务" @add="startAdd(branch)"><div v-for="item in tree(doc[branch]||[],branch)" :key="item.task.id" class="native-block-item" :style="{marginLeft:item.depth*15+'px'}"><small v-if="item.parent">{{item.parent}} / {{item.branch}}</small><LeafBlockCard :block="item.task" :path="item.path" :selected="selected===item.task.id" :focused="selected===item.task.id" :showOpenSplit="false" :showDuplicate="false" :runnable="false" :draggable="!readOnly" @drag-start="dragged=item.task.id" @drag-end="dragged=''" @drop="reorder(item.task.id)" @select="selected=item.task.id" @delete="edit(d=>removeTask(d,item.task.id))"/></div></BlockSectionCard></template></section><aside class="native-inspector"><div class="native-panel-caption">PROPERTIES</div><template v-if="step"><h3>{{step.id}}</h3><label>类型<select :value="step.kind" :disabled="readOnly" @change="stepField('kind',value($event))"><option>bash</option><option>python</option><option>command</option></select></label><label>脚本<NativeCodeEditor :source="step.command||''" :readOnly="readOnly" :path="step.id+(step.kind==='python'?'.py':'.sh')" :language="step.kind==='python'?'python':'shell'" :theme="theme" @change="v=>stepField('command',v)" @save="emit('save')"/></label><KsButton :disabled="readOnly" @click="emit('files',step.id)">从 Files 载入脚本</KsButton><label>前置步骤<select multiple :value="step.depends_on" :disabled="readOnly" @change="stepField('depends_on',Array.from(($event.target as HTMLSelectElement).selectedOptions,o=>o.value))"><option v-for="other in steps.filter(s=>s.id!==step.id)" :key="other.id">{{other.id}}</option></select></label><label>输出绑定 JSON<textarea :value="JSON.stringify(step.inputs||{},null,2)" :disabled="readOnly" @change="stepJSON(value($event))"/></label></template>
<template v-else-if="task"><h3>{{task.id}}</h3><code>{{task.type}}</code><label>Description<input :value="task.description||''" :disabled="readOnly" @change="field('description',value($event))"/></label><label v-for="name in ['message','condition','namespace','flowId','timeout'] .filter(k=>k in task||k==='timeout')" :key="name">{{name}}<input :value="task[name]||''" :disabled="readOnly" @change="field(name,value($event))"/></label><label v-if="'script' in task">Inline script<NativeCodeEditor :source="task.script||''" :readOnly="readOnly" :path="task.id+(task.type.includes('.python.')?'.py':'.sh')" :language="task.type.includes('.python.')?'python':'shell'" :theme="theme" @change="v=>field('script',v)" @save="emit('save')"/></label><label v-if="'values' in task">Values<textarea :value="typeof task.values==='string'?task.values:JSON.stringify(task.values,null,2)" :disabled="readOnly" @change="valuesField(value($event))"/></label><label>额外重试次数<input type="number" min="0" max="10" :value="Math.max(0,(task.retry?.maxAttempts||1)-1)" :disabled="readOnly||task.type==='io.kestra.plugin.core.http.Request'" @change="retry(Number(value($event)))"/></label><div class="native-inspector-actions"><KsButton :disabled="readOnly" size="small" @click="edit(d=>moveTask(d,task.id,-1))">上移</KsButton><KsButton :disabled="readOnly" size="small" @click="edit(d=>moveTask(d,task.id,1))">下移</KsButton><KsButton :disabled="readOnly" size="small" @click="startAdd('tasks',task.id)">添加子任务</KsButton></div><p class="native-note">未知插件字段保留。完整参数及复杂分支可在 YAML 编辑。</p></template>
<template v-else-if="doc"><h3>{{doc.id||'New Flow'}}</h3><label>Namespace<input :value="doc.namespace" readonly/></label><label>Flow 并发<input type="number" min="1" max="64" :value="doc.concurrency?.limit||1" :disabled="readOnly" @change="edit(d=>d.concurrency={limit:Number(value($event)),behavior:'QUEUE'})"/></label><label v-if="controlled">设备通道<select :value="inputDefault(doc,'transport_policy','agent_preferred')" :disabled="readOnly" @change="edit(d=>setDefault(d,'transport_policy',value($event)))"><option value="agent_preferred">Agent Preferred</option><option value="agent_only">Agent Only</option><option value="ssh_only">SSH Only</option></select></label><label v-for="input in (doc.inputs||[]).filter(i=>!['ticket','targets','steps'].includes(i.id))" :key="input.id">{{input.id}}<input :value="input.type==='SECRET'?'':typeof input.defaults==='object'?JSON.stringify(input.defaults):input.defaults" :placeholder="input.type==='SECRET'?'受控秘密引用':input.type" :disabled="readOnly||input.type==='SECRET'" @change="edit(d=>setDefault(d,input.id,value($event),input.type))"/></label><label>新任务区域<select v-model="addBranch"><option value="tasks">Tasks</option><option value="errors">On error</option><option value="finally">Finally</option></select></label><KsButton :disabled="readOnly" @click="startAdd(addBranch)">添加任务</KsButton></template></aside>
<KsDialog v-model="adding" title="添加任务" :teleported="false" :appendToBody="false" width="500px"><label v-if="addParent&&taskList(doc||{}).find(t=>t.id===addParent)?.type.endsWith('.If')">插入分支<select v-model="addBranch"><option value="then">Then</option><option value="else">Else</option></select></label><div class="native-task-picker"><KsButton v-for="item in catalog" :key="item.type" :disabled="readOnly" @click="addTask(item.type)"><Console :size="18"/><span>{{item.label}}</span><small>{{item.type.split('.').slice(-2).join('.')}}</small></KsButton></div></KsDialog></div></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import YAML from 'yaml';
import BlockSectionCard from '../../vendor/kestra/no-code/BlockSectionCard.vue';import LeafBlockCard from '../../vendor/kestra/no-code/LeafBlockCard.vue';
import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';import Console from 'vue-material-design-icons/Console.vue';import ViewSequential from 'vue-material-design-icons/ViewSequential.vue';
import NativeCodeEditor from './NativeCodeEditor.vue';
import {branches,taskList,locate,removeTask,moveTask,isControlled,inputDefault,setDefault,checkStructure,connectSteps,type Definition,type Task} from '../flows/definition';
const props=defineProps<{source:string;readOnly:boolean;theme:'dark'|'light';selected:string}>();const emit=defineEmits(['change','save','files','select']);
const selected=computed({get:()=>props.selected,set:value=>emit('select',value)}),error=ref(''),adding=ref(false),addBranch=ref('tasks'),addParent=ref(''),dragged=ref('');
const doc=computed<Definition|null>(()=>{try{const d=YAML.parse(props.source);checkStructure(d);return d}catch{return null}}),controlled=computed(()=>!!doc.value&&isControlled(doc.value));
const steps=computed<any[]>(()=>doc.value?inputDefault(doc.value,'steps',[]):[]),step=computed(()=>steps.value.find(s=>'step:'+s.id===selected.value)),task=computed(()=>doc.value?taskList(doc.value).find(t=>t.id===selected.value):null);
const catalog=[['Log','io.kestra.plugin.core.log.Log'],['Parallel','io.kestra.plugin.core.flow.Parallel'],['Condition','io.kestra.plugin.core.flow.If'],['Loop','io.kestra.plugin.core.flow.Loop'],['Subflow','io.kestra.plugin.core.flow.Subflow'],['Output Values','io.kestra.plugin.core.output.OutputValues']].map(([label,type])=>({label,type}));
const value=(event:Event)=>(event.target as HTMLInputElement).value;
function edit(fn:(d:Definition)=>void){if(props.readOnly)return;try{const d=YAML.parse(props.source);fn(d);checkStructure(d);emit('change',YAML.stringify(d));error.value=''}catch(e){error.value=String(e)}}
function tree(tasks:Task[],branch:string,parent='',depth=0):{task:Task;path:string;parent:string;branch:string;depth:number}[]{return tasks.flatMap((task,i)=>[{task,path:`${branch}[${i}]`,parent,branch,depth},...branches.flatMap(b=>tree(task[b]||[],b,task.id,depth+1))])}
function reorder(target:string){if(!dragged.value||dragged.value===target)return;edit(d=>{const from=locate(d,dragged.value),to=locate(d,target);if(!from||!to||from.list!==to.list)throw Error('只能在同一任务分支内拖动排序');const [item]=from.list.splice(from.index,1);from.list.splice(from.list.findIndex(t=>t.id===target),0,item)});dragged.value=''}
function field(key:string,value:unknown){edit(d=>{const found=locate(d,selected.value);if(found)found.list[found.index][key]=value})}
function retry(extra:number){if(!Number.isInteger(extra)||extra<0||extra>10){error.value='重试次数应为 0–10';return}edit(d=>{const f=locate(d,selected.value);if(!f)return;if(extra)f.list[f.index].retry={type:'constant',maxAttempts:extra+1,interval:'PT1S'};else delete f.list[f.index].retry})}
function valuesField(value:string){try{field('values',task.value?.type.endsWith('.OutputValues')?JSON.parse(value):value)}catch{error.value='Values 必须是 JSON 对象'}}
function stepField(key:string,value:unknown){edit(d=>{const all=inputDefault(d,'steps',[]),item=all.find((s:any)=>'step:'+s.id===selected.value);if(!item)return;if(key==='depends_on'){item.depends_on=[];for(const id of value as string[])connectSteps(all,id,item.id)}else item[key]=value;setDefault(d,'steps',all,'JSON')})}
function stepJSON(value:string){try{stepField('inputs',JSON.parse(value))}catch{error.value='输出绑定必须是 JSON 对象'}}
function removeStep(id:string){edit(d=>{const all=inputDefault(d,'steps',[]);if(all.some((s:any)=>s.depends_on.includes(id)||Object.values(s.inputs||{}).includes(id)))throw Error('先解除引用此步骤的依赖和输出绑定');setDefault(d,'steps',all.filter((s:any)=>s.id!==id),'JSON')})}
function addStep(){edit(d=>{const all=inputDefault(d,'steps',[]);const id='step_'+crypto.randomUUID().slice(0,6);all.push({id,kind:'bash',command:'',depends_on:all.length?[all.at(-1).id]:[],inputs:{}});setDefault(d,'steps',all,'JSON');selected.value='step:'+id})}
function startAdd(branch:string,parent=''){if(props.readOnly)return;addBranch.value=parent&&taskList(doc.value||{}).find(t=>t.id===parent)?.type.endsWith('.If')?'then':branch;addParent.value=parent;adding.value=true}
function addTask(type:string){edit(d=>{const id='task_'+crypto.randomUUID().slice(0,6);const item:Task={id,type};if(type.endsWith('.Script'))item.script=type.includes('.python.')?'#!/usr/bin/env python3\n':'#!/usr/bin/env bash\nset -euo pipefail\n';if(type.endsWith('.Log'))item.message='';if(type.endsWith('.Parallel'))item.tasks=[];if(type.endsWith('.If'))Object.assign(item,{condition:'',then:[],else:[]});if(type.endsWith('.Loop'))Object.assign(item,{values:'{{ inputs.items }}',tasks:[],concurrencyLimit:8});if(type.endsWith('.Subflow'))Object.assign(item,{namespace:d.namespace,flowId:''});if(type.endsWith('.OutputValues'))item.values={};const parent=addParent.value?taskList(d).find(t=>t.id===addParent.value):d;if(!parent)throw Error('父任务不存在');if(parent!==d&&!branches.some(b=>Array.isArray(parent[b])))throw Error('该节点不支持子任务，请选择容器任务');const branch=parent===d?addBranch.value:parent.type.endsWith('.If')?(addBranch.value==='else'?'else':'then'):'tasks';parent[branch]||=[];parent[branch].push(item);selected.value=id});adding.value=false}
</script>
<style scoped>
.native-visual{height:100%;display:grid;grid-template-columns:minmax(240px,1fr) 275px;color:var(--ks-text-primary);font-size:12px}.native-blocks{padding:14px;overflow:auto}.native-panel-caption{display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.08em;color:var(--ks-text-secondary);margin-bottom:14px}.native-block-item{margin-bottom:8px}.native-block-item small{display:block;font:10px monospace;color:var(--ks-text-secondary);margin-bottom:3px}.native-inspector{padding:16px;border-left:1px solid var(--ks-border-default);overflow:auto;background:var(--ks-bg-surface)}.native-inspector label{display:block;font-size:11px;margin:14px 0;color:var(--ks-text-secondary)}.native-inspector input,.native-inspector select,.native-inspector textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;border:1px solid var(--ks-border-default);border-radius:4px;padding:8px;background:var(--ks-bg-input);color:var(--ks-text-primary);font:12px var(--ks-font-family-sans)}.native-inspector textarea{min-height:90px}.native-inspector code{font-size:10px;overflow-wrap:anywhere}.native-inspector :deep(.native-code-editor){height:280px;min-height:220px}.native-inspector-actions{display:flex;gap:6px;flex-wrap:wrap}.native-error{padding:10px;color:var(--ks-text-error)}.native-note{color:var(--ks-text-secondary);font-size:11px;line-height:1.6}.native-task-picker{display:grid;gap:8px}.native-task-picker :deep(button){justify-content:flex-start}.native-task-picker small{margin-left:auto;font:10px monospace}.native-readonly :deep(.leaf-block-card-actions),.native-readonly :deep(.block-section-add){display:none}@media(max-width:1250px){.native-visual{grid-template-columns:minmax(220px,1fr)}.native-inspector{border-left:0;border-top:1px solid var(--ks-border-default)}}
</style>
